"use client";
import {useEffect,useState} from "react";
import {Button} from "@/components/ui/button";
import {Input} from "@/components/ui/input";
import {useEditor} from "@/editor/use-editor";
import {processMediaAssets} from "@/media/processing";
import {useAssetsPanelStore} from "../assets-panel-store";
type Resource={id:string;name:string;url:string;kind:string;trashedAt?:string|null;image?:boolean};
export function NachoResources(){
 const editor=useEditor(),[items,setItems]=useState<Resource[]>([]),[query,setQuery]=useState(''),[busy,setBusy]=useState(false),[status,setStatus]=useState(''),[error,setError]=useState('');
 async function refresh(signal?:AbortSignal){setError('');try{const responses=await Promise.all([fetch('/nacho-api/gallery',{signal}),fetch('/nacho-api/projects',{signal})]);if(responses.some(r=>!r.ok))throw Error('Arranca primero Elite Editor Studio en el puerto 4310.');const [gallery,projects]=await Promise.all(responses.map(r=>r.json()));const rendered=projects.flatMap((p:{id:string;name:string;artifacts:Record<string,unknown>})=>{const type=p.artifacts.export?'export':p.artifacts.preview?'preview':null;return type?[{id:p.id+'-'+type,name:'Editado · '+p.name,url:`/api/projects/${p.id}/artifact?type=${type}`,kind:'video'}]:[];});setItems([...rendered,...gallery.filter((r:Resource)=>!r.trashedAt&&r.url)]);}catch(e){if((e as Error).name!=='AbortError')setError((e as Error).message);}}
 useEffect(()=>{const controller=new AbortController();void refresh(controller.signal);return()=>controller.abort();},[]);
 async function importResource(item:Resource){const active=editor.project.getActive();if(!active)return;setBusy(true);setError('');setStatus('Leyendo '+item.name);try{const r=await fetch(item.url.replace(/^\/api\//,'/nacho-api/'));if(!r.ok)throw Error('No se pudo leer el recurso');const blob=await r.blob(),extension=blob.type.startsWith('video/')?'.mp4':blob.type.startsWith('audio/')?'.wav':blob.type==='image/png'?'.png':'.jpg',name=/\.[a-z0-9]{2,5}$/i.test(item.name)?item.name:item.name+extension;const assets=await processMediaAssets({files:[new File([blob],name,{type:blob.type})],onProgress:({progress})=>setStatus('Preparando recurso: '+Math.round(progress)+' %')});if(!assets.length)throw Error('OpenCut no pudo interpretar este archivo');for(const asset of assets)await editor.media.addMediaAsset({projectId:active.metadata.id,asset});setStatus('Añadido a Medios. Arrástralo a la timeline.');useAssetsPanelStore.getState().setActiveTab('media');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
 return <div className="flex h-full flex-col gap-3 overflow-y-auto p-3"><h2 className="font-semibold">Biblioteca Elite Editor WEB3</h2><p className="text-muted-foreground text-xs">Importa tus vídeos, sonidos y resultados automáticos del estudio local. Un resultado procesado se importa como un único clip, sin sus cortes editables.</p><Input aria-label="Buscar recursos Nacho" placeholder="Buscar…" value={query} onChange={e=>setQuery(e.target.value)}/><Button disabled={busy} variant="outline" onClick={()=>void refresh()}>Actualizar biblioteca</Button>{error?<p role="alert" className="text-xs text-red-400">{error}</p>:null}{status?<p role="status" className="text-xs">{status}</p>:null}<div className="flex flex-col gap-2">{items.filter(i=>i.name.toLocaleLowerCase().includes(query.toLocaleLowerCase())).map(i=><div key={i.id} className="rounded border p-2"><p className="truncate text-xs" title={i.name}>{i.name}</p><Button disabled={busy} size="sm" variant="outline" className="mt-2" onClick={()=>void importResource(i)}>Añadir a Medios</Button></div>)}</div><Button variant="outline" onClick={()=>useAssetsPanelStore.getState().setActiveTab("assistant")}>Abrir Asistente IA</Button></div>;
}
